const sqlRegistrarAcao = (acao) => {
  const situacao = acao.acao === 'LIBERACAO' ? 'LIBERADO' : 'BLOQUEADO';
  const merge = acao.sucesso
    ? `
MERGE dbo.CtlCnnControlePaciente WITH (HOLDLOCK) AS destino
USING (SELECT ${sqlN(acao.idPaciente)} AS IdPaciente) AS origem
    ON destino.IdPaciente = origem.IdPaciente
WHEN MATCHED THEN
    UPDATE SET
        NomePaciente = COALESCE(${sqlS(acao.nomePaciente, 200)}, destino.NomePaciente),
        Situacao = ${sqlS(situacao, 20)},
        IdAgendaReferencia = ${sqlN(acao.idAgenda)},
        NumeroFalta = ${sqlN(acao.numeroFalta)},
        DataInicioBloqueio = ${sqlDate(acao.dataInicioBloqueio)},
        DataFimBloqueio = ${sqlDate(acao.dataFimBloqueio)},
        UltimaAcao = ${sqlS(acao.acao, 20)},
        OrigemUltimaAcao = ${sqlS(acao.origem, 20)},
        UltimaAcaoPor = ${sqlS(acao.usuario, 100)},
        MotivoUltimaAcao = ${sqlS(acao.motivo, 500)},
        IdUltimaAcao = @IdAcao,
        UltimaAcaoEm = SYSUTCDATETIME()
WHEN NOT MATCHED THEN
    INSERT (
        IdPaciente, NomePaciente, Situacao, IdAgendaReferencia, NumeroFalta,
        DataInicioBloqueio, DataFimBloqueio, UltimaAcao, OrigemUltimaAcao,
        UltimaAcaoPor, MotivoUltimaAcao, IdUltimaAcao
    )
    VALUES (
        ${sqlN(acao.idPaciente)}, ${sqlS(acao.nomePaciente, 200)}, ${sqlS(situacao, 20)}, ${sqlN(acao.idAgenda)}, ${sqlN(acao.numeroFalta)},
        ${sqlDate(acao.dataInicioBloqueio)}, ${sqlDate(acao.dataFimBloqueio)}, ${sqlS(acao.acao, 20)}, ${sqlS(acao.origem, 20)},
        ${sqlS(acao.usuario, 100)}, ${sqlS(acao.motivo, 500)}, @IdAcao
    );`
    : '';

  return `USE INTEGRACAO;
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;

INSERT INTO dbo.CtlCnnAcaoPaciente (
    IdPaciente, NomePaciente, Acao, Origem, Usuario, Motivo,
    IdAgendaReferencia, NumeroFalta, DataInicioBloqueio, DataFimBloqueio,
    Antecipada, AtivoAntes, Sucesso, HttpStatus, RespostaApi, IdExecucaoN8n
)
VALUES (
    ${sqlN(acao.idPaciente)}, ${sqlS(acao.nomePaciente, 200)}, ${sqlS(acao.acao, 20)}, ${sqlS(acao.origem, 20)}, ${sqlS(acao.usuario || 'desconhecido', 100)}, ${sqlS(acao.motivo, 500)},
    ${sqlN(acao.idAgenda)}, ${sqlN(acao.numeroFalta)}, ${sqlDate(acao.dataInicioBloqueio)}, ${sqlDate(acao.dataFimBloqueio)},
    ${sqlBit(Boolean(acao.antecipada))}, ${sqlBit(acao.ativoAntes)}, ${sqlBit(Boolean(acao.sucesso))}, ${sqlN(acao.httpStatus)}, ${sqlS(acao.respostaApi, 1000)}, ${sqlS(acao.idExecucao, 50)}
);

DECLARE @IdAcao BIGINT = CONVERT(BIGINT, SCOPE_IDENTITY());
${merge}

COMMIT TRANSACTION;

SELECT @IdAcao AS IdAcao, CAST(${sqlBit(Boolean(acao.sucesso))} AS bit) AS Sucesso;`;
};
// ===== fim dos helpers de SQL =====

// Nó "preparar insert SQL" (bloqueio às 01:00 e botão Bloquear do painel).
// Monta o lote inteiro do nó "gravar faltas": um IF NOT EXISTS + INSERT por falta e a renumeração do ciclo.
const ehRespostaValida = (payload, campoId) => {
  return Boolean(payload && payload[campoId] != null && !payload.error && !payload.message);
};

const inicioPeriodo = inicioCiclo();
const faltas = $('separar faltas').all().filter((item) => !item.json.semFaltas);
const pacientes = $('GET paciente por id').all();
const executores = $input.all();

if (!faltas.length) {
  return [];
}

const inserts = faltas.map((item, indice) => {
  const falta = item.json ?? {};
  const paciente = pacientes[indice]?.json ?? {};
  const executor = executores[indice]?.json ?? {};
  const pacienteOk = ehRespostaValida(paciente, 'id');
  const executorOk = ehRespostaValida(executor, 'id');
  const contato = pacienteOk ? (paciente.contato ?? {}) : {};

  return `
IF NOT EXISTS (
    SELECT 1
    FROM dbo.CtlCnnFaltaPaciente
    WHERE IdAgenda = ${sqlN(falta.id)}
)
BEGIN
    INSERT INTO dbo.CtlCnnFaltaPaciente (
        IdAgenda,
        IdPaciente,
        NomePaciente,
        CpfCnpj,
        EmailPaciente,
        TelefonePaciente,
        DataFalta,
        HoraInicio,
        HoraFim,
        StatusAgenda,
        IdPessoaExecutor,
        IdExecutorAgenda,
        NomeExecutor,
        TipoExecutor,
        IdLocalAgenda,
        IdTipoConsulta,
        Observacoes,
        NumeroFalta
    )
    SELECT
        ${sqlN(falta.id)},
        ${sqlN(falta.idPaciente)},
        ${sqlS(pacienteOk ? paciente.nome : null, 200)},
        ${sqlS(pacienteOk ? paciente.cpfcnpj : null, 20)},
        ${sqlS(contato.email || falta.emailPaciente, 200)},
        ${sqlS(contato.telefoneCelular || falta.telefoneCelularPaciente, 30)},
        ${sqlDate(falta.dataFalta || falta.data)},
        ${sqlTime(falta.horaInicio)},
        ${sqlTime(falta.horaFim)},
        ${sqlS(falta.status, 50)},
        ${sqlN(falta.idPessoaExecutor)},
        ${sqlN(executorOk ? executor.id : null)},
        ${sqlS(executorOk ? executor.nome : null, 200)},
        ${sqlS(executorOk ? executor.tipoExecutor : null, 50)},
        ${sqlN(falta.idLocalAgenda)},
        ${sqlN(falta.idTipoConsulta)},
        ${sqlS(falta.observacoes, 500)},
        ISNULL((
            SELECT COUNT(1)
            FROM dbo.CtlCnnFaltaPaciente
            WHERE IdPaciente = ${sqlN(falta.idPaciente)}
              AND DataFalta >= CONVERT(date, '${inicioPeriodo}', 23)
        ), 0) + 1;
END`;
}).join('\n');

const idsPacientes = [...new Set(
  faltas
    .map((item) => Number(item.json.idPaciente))
    .filter((id) => Number.isFinite(id))
)];
const listaIds = idsPacientes.join(', ');

// Depois dos inserts, reordena NumeroFalta por data dentro do ciclo (uma falta antiga pode chegar depois de uma nova).
const query = `USE INTEGRACAO;
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;

${inserts}

;WITH Numeracao AS (
    SELECT
        Id,
        ROW_NUMBER() OVER (
            PARTITION BY IdPaciente
            ORDER BY DataFalta, IdAgenda
        ) AS NumeroCalculado
    FROM dbo.CtlCnnFaltaPaciente
    WHERE IdPaciente IN (${listaIds})
      AND DataFalta >= CONVERT(date, '${inicioPeriodo}', 23)
)
UPDATE destino
SET NumeroFalta = origem.NumeroCalculado
FROM dbo.CtlCnnFaltaPaciente AS destino
INNER JOIN Numeracao AS origem
    ON origem.Id = destino.Id
WHERE destino.NumeroFalta <> origem.NumeroCalculado;

COMMIT TRANSACTION;

SELECT CAST(${faltas.length} AS int) AS faltasProcessadas;`;

return [{
  json: {
    query,
    quantidadeFaltas: faltas.length,
    dataInicioPeriodo: inicioPeriodo,
    idsPacientes,
    listaIds
  }
}];

